import {Platform} from 'react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import * as Keychain from 'react-native-keychain';
import ReactNativeBiometrics from 'react-native-biometrics';

export const BIOMETRIC_ENABLED_KEY = 'isBiometricEnabled';
export const BIOMETRIC_ENABLED_VALUE = 'enabled';
export const BIOMETRIC_DISABLED_VALUE = 'disabled';

export const isFingerprintUnlockPlatform = (): boolean => Platform.OS === 'android';

export const getUnlockSettingI18nKey = (): string =>
  isFingerprintUnlockPlatform() ? 'loginByTouchID' : 'loginByFaceID';

export const getUnlockConfirmTitleI18nKey = (): string =>
  isFingerprintUnlockPlatform()
    ? 'biometricUnlockConfirmTitleTouch'
    : 'biometricUnlockConfirmTitleFace';

export const getUnlockConfirmBodyI18nKey = (): string =>
  isFingerprintUnlockPlatform()
    ? 'biometricUnlockConfirmBodyTouch'
    : 'biometricUnlockConfirmBodyFace';

export const isBiometricUnlockEnabled = async (): Promise<boolean> => {
  const value = await AsyncStorage.getItem(BIOMETRIC_ENABLED_KEY);
  return value === BIOMETRIC_ENABLED_VALUE;
};

export const setBiometricUnlockEnabled = async (
  enabled: boolean,
): Promise<void> => {
  await AsyncStorage.setItem(
    BIOMETRIC_ENABLED_KEY,
    enabled ? BIOMETRIC_ENABLED_VALUE : BIOMETRIC_DISABLED_VALUE,
  );
};

export const hasUnlockableSession = async (): Promise<boolean> => {
  const memberData = await AsyncStorage.getItem('memberData');
  if (!memberData) {
    return false;
  }

  const token = await Keychain.getGenericPassword();
  return Boolean(token && token.password.length > 8);
};

export const promptBiometricUnlock = async (): Promise<boolean> => {
  const rnBiometrics = new ReactNativeBiometrics();
  try {
    const result = await rnBiometrics.simplePrompt({
      promptMessage: $i18n.t('biometricUnlockPrompt'),
    });
    return result.success === true;
  } catch {
    return false;
  }
};

export interface BiometricLockOverlayProps {
  visible: boolean;
  onUnlockSuccess: () => void;
  onUseEmailLogin: () => void;
}

import EStyleSheet from 'react-native-extended-stylesheet';

export default EStyleSheet.create({
  modalBackground: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: '#FFFFFF',
    paddingHorizontal: 24,
  },
