    borderRadius: 8,
    alignItems: 'center',
    justifyContent: 'center',
    height: 42,
    width: 180,
    backgroundColor: '#00AC86',
    marginBottom: 12,
  },
  retryText: {
    color: '#FFFFFF',
    fontSize: 14,
    fontWeight: '700',
  },
