import React, {useCallback, useEffect, useRef} from 'react';
import {AppState, Modal, View} from 'react-native';
import AppText from '@components/app-text/app-text';
import {ThemeContext} from '@style/theme/theme-context.tsx';
import type {Theme} from '@types/Theme.ts';
import FaceID from '../../assets/images/face_id.svg';
import TouchID from '../../assets/images/touch_id.svg';
import {
  getUnlockConfirmBodyI18nKey,
  getUnlockSettingI18nKey,
  isFingerprintUnlockPlatform,
  promptBiometricUnlock,
} from '@utils/biometric-unlock';
import {BiometricLockOverlayProps} from './biometric-lock-overlay.props';
import styles from './biometric-lock-overlay.styles';

const BiometricLockOverlay: React.FC<BiometricLockOverlayProps> = ({
  visible,
  onUnlockSuccess,
  onUseEmailLogin,
}) => {
  const isPromptingRef = useRef<boolean>(false);

  const promptUnlock = useCallback(async (): Promise<void> => {
    if (!visible || isPromptingRef.current) {
      return;
    }

    isPromptingRef.current = true;
    try {
      const unlocked = await promptBiometricUnlock();
      if (unlocked) {
        onUnlockSuccess();
      }
    } finally {
      isPromptingRef.current = false;
    }
  }, [onUnlockSuccess, visible]);

  useEffect(() => {
    if (!visible) {
      return;
    }

    const subscription = AppState.addEventListener('change', (nextState) => {
      if (nextState === 'active') {
        void promptUnlock();
      }
    });

    if (AppState.currentState === 'active') {
      void promptUnlock();
    }

    return () => {
      subscription.remove();
    };
  }, [promptUnlock, visible]);

  return (
    <ThemeContext.Consumer>
      {(_theme: Theme) => (
        <Modal
          animationType="fade"
          transparent={false}
          visible={visible}
          onRequestClose={() => {
            void promptUnlock();
          }}
        >
          <View style={styles.modalBackground}>
            <View style={styles.iconWrap}>
              {isFingerprintUnlockPlatform() ? (
                <TouchID height={64} width={64} />
              ) : (
                <FaceID height={64} width={64} />
              )}
            </View>
            <AppText style={styles.title}>
              {$i18n.t(getUnlockSettingI18nKey())}
            </AppText>
            <AppText style={styles.body}>
              {$i18n.t(getUnlockConfirmBodyI18nKey())}
            </AppText>
            <View
              accessibilityRole="button"
              onTouchEnd={() => {
                void promptUnlock();
              }}
              style={styles.retryButton}
            >
              <AppText style={styles.retryText}>
                {$i18n.t('biometricUnlockRetry')}
              </AppText>
            </View>
            <View
              accessibilityRole="button"
              onTouchEnd={onUseEmailLogin}
              style={styles.emailButton}
            >
              <AppText style={styles.emailText}>
                {$i18n.t('biometricUnlockUseEmailLogin')}
              </AppText>
            </View>
          </View>
        </Modal>
      )}
    </ThemeContext.Consumer>
  );
};

export default BiometricLockOverlay;

import React, { useEffect, useState, } from 'react';
import {
  View,
  Image,
  TouchableOpacity,
  Modal,
  Switch,
} from 'react-native';
import AppText from '@components/app-text/app-text';
import styles from './profile-settings-screen.styles';
import {ThemeContext} from "@style/theme/theme-context.tsx";
import type { Theme } from "@types/Theme.ts";
import NavigationBar from '@components/navigation-bar/navigation-bar.tsx';
import PageRightBt from '@components/page-right-bt/page-right-bt.tsx';
import LogoutModal from '@components/logout-modal/logout-modal';
import DeleteAccountModal from '@components/delete-account-modal/delete-account-modal';
import {useAppState} from '@store/AppContext';
import FaceID from '../../../assets/images/face_id.svg';
import TouchID from '../../../assets/images/touch_id.svg';
import LanguageButtonComponent from '@components/language-bottom-sheet-component/language-bottom-sheet-component';
import {
  getUnlockConfirmBodyI18nKey,
  getUnlockConfirmTitleI18nKey,
  getUnlockSettingI18nKey,
  isBiometricUnlockEnabled,
  isFingerprintUnlockPlatform,
  promptBiometricUnlock,
  setBiometricUnlockEnabled,
} from '@utils/biometric-unlock';

const SettingsScreen = () => {
  const {
    setLogoutModal,
    setCommonModalKey
  } = useAppState();
  const [showModal, setShowModal] = useState(false);
  const [enabledBiometric, setEnabledBiometric] = useState(false);
  const [showUseBiometricConfirm, setShowBiometricConfirm] = useState(false);
  const [openLogoutModal, setOpenLogoutModal] = useState<boolean>(false);

  useEffect(
    () => {
      initializeSettings();
    }, []);

  const initializeSettings = async () => {
    const enabled = await isBiometricUnlockEnabled();
    setEnabledBiometric(enabled);
  }

  const handleSwitchEnabledBiometric = async () => {
    if (!enabledBiometric) {
      setEnabledBiometric(true);
      setShowBiometricConfirm(true)
    } else {
      setEnabledBiometric(false);
      await setBiometricUnlockEnabled(false);
    }
  }

  const handleConfirmBiometric = async () => {
    setShowBiometricConfirm(false);
    const unlocked = await promptBiometricUnlock();
    if (unlocked) {
      setEnabledBiometric(true);
      await setBiometricUnlockEnabled(true);
    } else {
      setEnabledBiometric(false);
      await setBiometricUnlockEnabled(false);
    }
  }

  const handleCancelBiometric = async () => {
    setEnabledBiometric(false);
    setShowBiometricConfirm(false);
  }

  const handleLogout = () => {
    // setOpenLogoutModal(true);
    setCommonModalKey($routeNames.settingsScreen+'Button');
    setLogoutModal(true);
  }

  const renderBiometricConfirmation = () => {
    return (
      <Modal
        animationType="slide"
        transparent={true}
        visible={showUseBiometricConfirm}
        onRequestClose={() => setShowBiometricConfirm(false)}
      >
        <View style={[styles.modalBackground, { pointerEvents: 'box-none' }]}>
          <View style={styles.modalContainer}>
            <View style={{ marginBottom: 16 }}>
              {isFingerprintUnlockPlatform()
                ? <TouchID height={64} width={64} />
                : <FaceID height={64} width={64} />
              }

            </View>
            <AppText style={styles.modalTitle}>
              {$i18n.t(getUnlockConfirmTitleI18nKey())}
            </AppText>
            <AppText style={{ textAlign: 'center' }}>
              {$i18n.t(getUnlockConfirmBodyI18nKey())}
            </AppText>
            <View
              style={{
                flexDirection: 'row',
                width: 300,
                alignSelf: 'center',
                justifyContent: 'center',
                alignItems: 'center',
                marginTop: 16,

              }}
            >
              <TouchableOpacity style={{
                borderColor: '#E1EBEC',
                borderWidth: 1,
                borderRadius: 8,
                alignItems: 'center',
                height: 42,
                justifyContent: 'center',
                width: 99
              }}
                onPress={() => handleCancelBiometric()}
              >
                <AppText style={{ color: '#00AC86', fontSize: 14, fontWeight: 700 }}>{$i18n.t('cancel')}</AppText>
              </TouchableOpacity>
              <View style={{ width: 8 }} />
              <TouchableOpacity style={{
                borderColor: '#E1EBEC',
                borderWidth: 1,
                borderRadius: 8,
                alignItems: 'center',
                height: 42,
                justifyContent: 'center',
                width: 99,
                backgroundColor: '#00AC86'
              }}
                onPress={() => handleConfirmBiometric()}
              >
                <AppText style={{ color: '#fff', fontSize: 14, fontWeight: 700 }}>{$i18n.t('confirm')}</AppText>
              </TouchableOpacity>
            </View>
          </View>
        </View>
      </Modal>
    )
  }

  const renderBiometricSettings = () => {
    return (
      <TouchableOpacity style={styles.touchItem}
        onPress={() => {
          handleSwitchEnabledBiometric();
        }}
      >
        <AppText
          style={styles.itemText}>
          {$i18n.t(getUnlockSettingI18nKey())}
        </AppText>
        <Switch
          value={enabledBiometric}
          onValueChange={() => handleSwitchEnabledBiometric()}
          thumbColor={'white'} // Custom thumb color based on state
          trackColor={{ false: 'gray', true: '#00AC86' }}
          style={{ transform: [{ scale: 0.78 }] }}
        />
      </TouchableOpacity>
    )
  }

  return (
    <ThemeContext.Consumer>
      {(theme: Theme) => {
        return (
          <>
            <View style={styles.container}>
              <NavigationBar title={$i18n.t('setting.title')}
                rightBt={<PageRightBt tag={$routeNames.settingsScreen} />}
              />
              <View style={styles.topView}>
                <LanguageButtonComponent />
                <TouchableOpacity style={[styles.touchItem, {
                  borderBottomWidth: 1,
                  borderBottomColor: '#3965611A'
                }]}
                  onPress={() => {
                    console.log('Delete account click');
                    setShowModal(true);
                  }}
                >
                  <AppText style={styles.itemText}>{$i18n.t('setting.deleteAccount')}</AppText>
                  <Image source={$assets.arrowR()} style={{ width: 24, height: 24 }} />
                </TouchableOpacity>
                {renderBiometricSettings()}
              </View>
              <TouchableOpacity style={styles.bottomView}
                onPress={() => handleLogout()}
              >
                <AppText style={{ color: '#D1224D', fontSize: 14, fontWeight: 700 }}>{$i18n.t('logout')}</AppText>
              </TouchableOpacity>
            </View>
            <DeleteAccountModal
              visible={showModal}
              onClose={() => setShowModal(false)}
            />
            {renderBiometricConfirmation()}
            {/* <LogoutModal open={openLogoutModal} handleCancle={() => setOpenLogoutModal(false)}/> */}
              <LogoutModal tag={$routeNames.settingsScreen+'Button'}></LogoutModal>
          </>
        );
      }}
    </ThemeContext.Consumer >
  );
};

export default SettingsScreen;

