const restoreSavedSession = async (): Promise<boolean> => {
  const memberDataRaw = await AsyncStorage.getItem("memberData");
  if (!memberDataRaw) {
    return false;
  }

  const memberData = JSON.parse(memberDataRaw) as LoginData;
  const accessToken = memberData?.accessToken;
  const globalAppState = getGlobalAppState();
  if (!accessToken) {
    return false;
  }

  const decoded = jwtDecode<{exp?: number}>(accessToken);
  const currentTime = Math.floor(Date.now() / 1000);

  if (decoded.exp !== undefined && decoded.exp < currentTime) {
    const payload = {
      "userId": memberData.entity.id,
      "refreshToken": memberData?.refreshToken
    }
    const response = await $api.refreshToken(payload);

    if (response?.success && response?.data?.accessToken) {
      await globalAppState?.setLoginData({
        ...memberData,
        accessToken: response.data.accessToken,
      });
      return true;
    }
    return false;
  }

  await globalAppState?.setLoginData(memberData);
  return true;
};

const authenticate = async () => {
  const biometricEnabled = await isBiometricUnlockEnabled();
  const unlockableSession = await hasUnlockableSession();

  if (biometricEnabled && unlockableSession) {
    const restored = await restoreSavedSession();
    if (restored) {
      setIsUserTokenValid(true);
      setIsAppLocked(true);
      setIsAuthChecking(false);
      return;
    }
  } else {
    const restored = await restoreSavedSession();
    if (restored) {
      setIsUserTokenValid(true);
      setIsAuthChecking(false);
      return;
    }
  }
  setIsAuthChecking(false);
};

const shouldLockAppOnState = (nextAppState: string): boolean => {
  if (Platform.OS === "ios") {
    return nextAppState === "inactive" || nextAppState === "background";
  }
  return nextAppState === "background";
};

const handleAppStateChange = (nextAppState: string) => {
  setAppState(nextAppState);
